%% main_reinforce.m
clear; close all; clc;

% 1. 环境设置 
% x_len = 5; y_len = 5;
% start = [1, 1]; final = [3, 4];
% obs = [2,2; 3,2; 3,3; 2,4; 4,4; 2,5];

% x_len = 2; y_len = 2;
% start = [1, 1]; final = [2, 2];
% obs = [1,2];

% x_len = 1; y_len = 2;
% start = [1, 1]; final = [1,2];
% obs = [1,1];

% x_len = 2; y_len = 3;
% start = [1, 1]; final = [2,3];
% obs = [2,2];

% x_len = 4; y_len = 4;
% start = [1, 1]; final = [2, 4];
% obs = [1,2; 1,3; 2,2; 3,2; 3,3];

x_len = 4; y_len = 4;
start = [1, 1]; final = [3, 4];
obs = [1,2; 1,3; 2,2; 3,2];

env = GridWorld(x_len, y_len, start, final, obs);
env.Reward_Forbidden = -10; % 触碰障碍的惩罚
env.Reward_Target = 1;

% 2. REINFORCE 算法参数
num_states = env.State_Space_Size;
num_actions = length(env.Action_Space);
alpha = 0.00001;        % 策略梯度学习率通常较小
gamma = 0.95;        % 折扣因子 γ
num_episodes = 3000; % 训练回合数
max_steps = 600;

% 3. 实例化 Agent
agent = REINFORCEAgentThetaTable(num_states, num_actions, alpha, gamma);

% 4. 训练过程
disp('Starting REINFORCE training strictly following Eq 9.33...'); %[output:37ebdc29]
tic; 
agent.train(env, num_episodes, max_steps); %[output:15f3f0be]
toc;  %[output:47729f94]

% 5. 结果可视化
% 5.1 回报收敛曲线
figure('Name', 'REINFORCE Learning Curve', 'Color', 'w'); %[output:93a85e7e]
window_size = 100; 
smoothed_returns = movmean(agent.returns_history, window_size);
plot(1:num_episodes, agent.returns_history, 'Color', [0.8 0.8 0.8]); hold on; %[output:93a85e7e]
plot(1:num_episodes, smoothed_returns, 'LineWidth', 2, 'Color', 'b'); %[output:93a85e7e]
title('Training Curve (Moving Average)'); %[output:93a85e7e]
xlabel('Episode'); ylabel('Return (G_t)'); grid on; %[output:93a85e7e]

% 5.2 绘制概率策略矩阵
policy_matrix = agent.get_policy_matrix();
env.plot_policy_matrix(policy_matrix); %[output:9d71430c]

% 5.3 按照学到的最优概率贪心生成一条测试轨迹
test_states = zeros(max_steps, 1);
curr_state = env.coord2idx(start);
test_states(1) = curr_state;
step_cnt = 1;

for step = 1:max_steps
    probs = agent.get_action_probabilities(curr_state);
    [~, best_a] = max(probs); % 贪婪策略测试 纯为了画图
    [next_s, ~, done] = env.step(curr_state, best_a);
    
    step_cnt = step_cnt + 1;
    test_states(step_cnt) = next_s;
    if done, break; end
    curr_state = next_s;
end
env.plot_trajectory(test_states(1:step_cnt)); %[output:6b06bfbe]



